import{_ as s,c as t,o as r,j as e,a as n}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"学易笔谈序","description":"杭氏易学 - 学易笔谈序","frontmatter":{"title":"学易笔谈序","description":"杭氏易学 - 学易笔谈序"},"headers":[],"relativePath":"zh/classics/hangshi/020.md","filePath":"zh/classics/hangshi/020.md"}'),i={name:"zh/classics/hangshi/020.md"};function c(o,a,l,d,h,p){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"学易笔谈序",tabindex:"-1"},[n("学易笔谈序 "),e("a",{class:"header-anchor",href:"#学易笔谈序","aria-label":"Permalink to “学易笔谈序”"},"​")],-1),e("p",null,"海宁先生之于《易》，得异人传授，又博极诸家传注，故能竟委穷源，而独见其大。先生于书，无所不读，故能探赜索隐，钩贯于新旧之学，而独得其通。昔尝闻之先生曰：《易》始于包牺氏，备于神农、黄帝，大明于文王、周公、孔子。汉人去古未远，其卦气、飞伏、阴阳、消息，皆有所授受，非能自创。孔子赞《易》，专重人道，以明立教之旨。故三陈九德，以人合天，而筮法仅略言及之。朱子乃谓“《易》为圣人教人卜筮之书”，岂知方耶？然河、洛为《易》象所取则，汉学只诋为伪造，朱子独取以冠经首，是其卓识，亦有不可及者。又曰：“道家祖黄老，渊源悉出于《易》。”其七返九还，六归八居，度数与卦象悉合无论矣。所异者佛产印度，耶稣生于犹太，而《华严》之乘数，《金刚》之相数，一八、三六、百零八之数，及“七日来复”、“十三见凶之数”，亦无不得。仅以素所闻于先生者，弁诸简端，并志其缘起如此云。",-1)])])}const f=s(i,[["render",c]]);export{_ as __pageData,f as default};
